mapper.select:
UPDATE gc_user_message
SET read_state = 1
WHERE target_user_id = #{userId} AND user_id = #{targetUserId} AND read_state = 0;

SELECT * FROM gc_user_message WHERE id IN ( SELECT MAX(id) FROM gc_user_message WHERE user_id IN
#{userId}
AND target_user_id = #{targetUserId} GROUP BY user_id )

select me.*,file.id as f_id,file.name as f_name,file.file_url as f_file_url,file.save_type as f_save_type from gc_user_message me
left join sys_file file on file.id = me.file_id
where me.type=#{messageType}

    and me.target_user_id=#{targetUserId}


    and me.targetManagerId=#{targetManagerId}
